When applied to trait method implementations, the attribute works as it does for regular functions. When applied to a trait method prototype, the attribute applies to all implementations of the method. When applied to a default trait method implementation, the attribute takes effect on that implementation and any overrides. Examples: #![feature(track_caller)] macro_rules! assert_tracked { () => {{ let location = std::panic::Location::caller(); assert_eq!(location.file(), file!()); assert_ne!(location.line(), line!(), "line should be outside this fn"); println!("called at {}", location); }};
} trait TrackedFourWays { /// All implementations inherit `#[track_caller]`. #[track_caller] fn blanket_tracked(); /// Implementors can annotate themselves. fn local_tracked(); /// This implementation is tracked (overrides are too). #[track_caller] fn default_tracked() { assert_tracked!(); } /// Overrides of this implementation are tracked (it is too). #[track_caller] fn default_tracked_to_override() { assert_tracked!(); }
} /// This impl uses the default impl for `default_tracked` and provides its own for
/// `default_tracked_to_override`.
impl TrackedFourWays for () { fn blanket_tracked() { assert_tracked!(); } #[track_caller] fn local_tracked() { assert_tracked!(); } fn default_tracked_to_override() { assert_tracked!(); }
} fn main() { <() as TrackedFourWays>::blanket_tracked(); <() as TrackedFourWays>::default_tracked(); <() as TrackedFourWays>::default_tracked_to_override(); <() as TrackedFourWays>::local_tracked();
}

